// (dup, drop, swap, over), and user-defined words introduced with the
// customary syntax ": word-name definition ;". Words are case-insensitive.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string][]string{}

	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			if tokens[i] != ":" {
				if err := execToken(tokens[i], &stack, words); err != nil {
					return nil, err
				}
				continue
			}
			// A definition: ": name body... ;"
			if i+2 >= len(tokens) {
				return nil, fmt.Errorf("malformed definition")
			}
			name := strings.ToLower(tokens[i+1])
